#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long val;
    int f;
} Node;

int cmp_desc(const void *a, const void *b) {
    int va = *(const int*)a;
    int vb = *(const int*)b;
    return (vb > va) - (vb < va);
}

void sift_down(Node *heap, int size, int idx) {
    while (1) {
        int left = idx * 2;
        int right = left + 1;
        int smallest = idx;
        if (left <= size && heap[left].val < heap[smallest].val) {
            smallest = left;
        }
        if (right <= size && heap[right].val < heap[smallest].val) {
            smallest = right;
        }
        if (smallest == idx) break;
        Node tmp = heap[idx];
        heap[idx] = heap[smallest];
        heap[smallest] = tmp;
        idx = smallest;
    }
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *T = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &T[i]);
    }
    qsort(T, N, sizeof(int), cmp_desc);

    Node *heap = (Node*)malloc((M + 1) * sizeof(Node));
    for (int i = 1; i <= M; i++) {
        int f;
        scanf("%d", &f);
        heap[i].val = 0;
        heap[i].f = f;
    }

    long long ans = 0;
    for (int i = 0; i < N; i++) {
        long long val = heap[1].val;
        int f = heap[1].f;
        ans += (long long)T[i] * val;
        heap[1].val = val + f;
        sift_down(heap, M, 1);
    }

    printf("%lld\n", ans);

    free(T);
    free(heap);
    return 0;
}
